/**
 * Interface copy.
 *
 * Every string is a message with named placeholders. Placeholders carry
 * operational identifiers — flight numbers, airport codes, times, gate names —
 * and are substituted verbatim, never translated.
 *
 * Machine-translated locales are produced by the AI layer at runtime for
 * free-text guidance. This catalogue covers the structural interface so the
 * product is usable in a language even when the AI layer is unavailable.
 */

