  "change.observedAirborne": "Aircraft with this callsign observed airborne",
  "change.observedOnGround": "Aircraft with this callsign observed on the ground",
  "change.observedAt": "Observed at {time}.",
  "rights.because.eu": "Your route involves an EU or EEA airport, or a carrier based there.",
  "rights.because.uk": "Your route involves a United Kingdom airport.",
  "rights.because.us": "Your route involves a United States airport.",
  "rights.because.ca": "Your route involves a Canadian airport.",
  "rights.because.montreal": "Your journey involves more than one country, so international carriage rules may apply.",
  "rec.captureAnnouncement.title": "Capture the announcement text if you can",
  "rec.captureAnnouncement.why": "A photograph or a few typed words is enough for WAYFINDER to translate it and explain what it means. Announcement wording often contains the specific gate, time or instruction that matters.",
  "rec.confirmWithAirline.title": "Confirm the flight's status directly with {airline}",
  "rec.confirmWithAirline.why": "No public source publishes per-flight status. The airline's own flight-status page is the only place that can confirm whether this specific flight is operating, delayed or cancelled. Check the airline's app or website rather than a third-party aggregator.",
  "rec.contactAirline.title": "Contact {airline} through its official channel",
  "rec.contactAirline.why": "Rebooking, refunds and care are handled by the operating airline, not by the airport and not by a booking site. Contacting them early generally means more options, because seats are reallocated in the order passengers are handled.",
  "rec.askRebooking.title": "Ask specifically about rebooking on the next available flight",
  "rec.askRebooking.why": "When a flight does not operate, airlines can usually move you to another of their flights, and sometimes to a partner airline. Ask what the earliest option is, and ask them to hold a seat while you decide.",
  "rec.askRefundOrCredit.title": "Ask whether you are being offered a refund or a credit",
  "rec.askRefundOrCredit.why": "A refund and a travel credit are not the same thing. Depending on where your journey starts and ends, you may be entitled to a refund if you choose not to travel. Ask which one you are being offered before accepting anything.",
  "rec.askDelayDuration.title": "Ask how long the delay is expected to last",
  "rec.askDelayDuration.why": "The length of a delay changes what you are entitled to and what you should do. Care such as meals and accommodation usually depends on how long you are waiting and whether the delay runs overnight.",
  "rec.checkConnection.title": "Check whether your onward flight is affected",
  "rec.checkConnection.why": "A delay on the first flight can cause you to miss a connection even when the second flight is operating normally. Ask the airline to confirm your connection status and to rebook the whole journey if needed.",
  "rec.dontAssumeProtection.title": "Do not assume your connection is protected",
  "rec.dontAssumeProtection.why": "Whether you are rebooked onto a later connection, and whether you are entitled to care or compensation, depends on your ticket, whether both flights are on one booking, and the rules that apply to your route. Get the airline to confirm in writing.",
  "rec.verifyGate.title": "Verify the new gate on an airport screen, not just a notification",
  "rec.verifyGate.why": "Gates change frequently and notifications can lag behind the airport's own displays. Airport screens and the airline's app are the most current places to check.",
  "rec.airportStatusUnavailable.title": "Check the airport's own operational status page",
  "rec.airportStatusUnavailable.why": "WAYFINDER could not retrieve current air traffic constraint information for your airports. The airport's website or the national air traffic provider will show whether there are restrictions in force.",
  "rec.weatherUnavailable.title": "Check the current weather at both airports",
  "rec.weatherUnavailable.why": "Weather observations could not be retrieved for one or both airports, so WAYFINDER cannot assess whether conditions are contributing to disruption. A national weather service will show current conditions.",
  "rec.openAviationWeather": "Open aviation weather",
  "rec.reviewRights.title": "Review the official passenger-rights guidance for your route",
  "rec.reviewRights.why": "What you are entitled to depends on where your journey starts and ends and which carrier operates it. Reading the official guidance for your route tells you what to ask for, and what you are not entitled to.",
  "rec.keepEvidence.title": "Keep your booking reference, boarding pass and receipts",
  "rec.keepEvidence.why": "If you need to claim expenses or compensation later, airlines ask for receipts and your booking reference. Collecting them now, while you are at the airport, is much easier than afterwards.",
  "rec.airportHelpDesk.title": "Ask the airline desk at {airport}, not a general information desk",
  "rec.airportHelpDesk.why": "Airport information desks can tell you about the airport, but only the airline can change your booking. Go to the airline's own service desk or transfer desk.",
  "rec.destinationArrangements.title": "If you will arrive late at {airport}, check onward arrangements",
  "rec.destinationArrangements.why": "Late arrival can affect ground transport, accommodation and onward travel. Notifying providers early often avoids losing a booking entirely.",

