  "preview.step1.title": "Confirm the flight's status with British Airways",
  "preview.step1.why": "No public source publishes per-flight status. The airline's own flight-status page is the only place that can confirm whether this flight is operating.",
  "preview.step2.title": "Ask about rebooking on the next available flight",
  "preview.step2.why": "Seats are reallocated in the order passengers are handled, so contacting the airline early generally means more options.",
  "preview.step3.title": "Check whether your onward connection is affected",
  "preview.step3.why": "A delay on the first leg can cause a missed connection even when the second flight is operating normally.",
