  "preview.src3.detail": "Reference route data. This is not live flight status.",
  "live.badge": "Live data",
  "live.title": "Every fact carries its source",
  "live.body": "WAYFINDER does not display a status it cannot verify. It queries the official operator or authority for the place you are in, records exactly when each answer arrived, and states plainly what it still cannot confirm.",
  "live.notShown.title": "What we deliberately do not show",
  "live.notShown.status.lead": "A per-flight status.",
  "live.notShown.status.body": "No public source we can reach publishes whether a specific flight is cancelled or delayed. Guessing would be worse than saying so.",
  "live.notShown.rights.lead": "A guaranteed entitlement.",
  "live.notShown.rights.body": "Refunds and compensation depend on your route, ticket and the cause of the disruption. We link to the official guidance instead.",
  "live.notShown.score.lead": "A confidence figure.",
  "live.notShown.score.body": "Scores imply precision we do not have. We describe the conditions and the reasoning instead.",
  "live.source": "Source:",
  "live.route.title": "Route and airline reference",
  "live.route.body": "Flight numbers resolve to a published route, airline and ICAO callsign, so every later lookup uses the right airport identifiers.",
  "live.transit.title": "Public-transport status",
  "live.transit.body": "Live line and service status from the operators themselves — Transport for London's tube, rail and bus lines, MTA New York subway alerts, and BART service advisories — with the operator's own severity wording.",
  "live.roads.title": "Roads and public notices",
  "live.roads.body": "Lane and road closures from Caltrans, and civic notices from GOV.UK, each carrying the publishing authority and the time it was retrieved.",
  "live.weather.title": "Severe weather and seismic events",
  "live.weather.body": "Active official warnings from NOAA / National Weather Service and Deutscher Wetterdienst, and recent seismic events from the USGS — with the issuing authority and the affected areas.",
  "live.airspace.title": "Airspace status",
  "live.airspace.body": "Ground delay and ground stop programmes, with the reason and average delay, for airports covered by the FAA.",
