  "how.title": "Cómo funciona WAYFINDER",
  "how.subtitle": "Cuatro pasos, diseñados para que veas exactamente de dónde viene cada dato.",
  "how.step1.title": "Cuéntanos qué ha pasado",
  "how.step1.body": "Elige la situación o descríbela con tus palabras. Sin cuenta y sin formularios innecesarios.",
  "how.step2.title": "Reunimos los datos",
  "how.step2.body": "WAYFINDER consulta las fuentes oficiales que cubren tu zona —operadores de transporte, autoridades de carretera, servicios meteorológicos y organismos públicos— y registra cuándo llegó cada respuesta.",
