  "uncertain.flightStatus": "Si este vuelo concreto se opera, lleva retraso o está cancelado. Ninguna fuente pública a la que podamos acceder publica el estado por vuelo.",
  "uncertain.scheduleDetails": "Las horas de salida y llegada programadas, la terminal y la puerta. Los publica la aerolínea y no están disponibles en nuestras fuentes.",
  "uncertain.itinerary": "Los aeropuertos de tu itinerario, porque no se publicó ninguna referencia de ruta para este número de vuelo.",
  "uncertain.whetherFlown": "Si la aeronave ha volado. La cobertura del seguimiento comunitario es incompleta, así que la ausencia de señal no significa que el vuelo no se operara.",
  "uncertain.weather": "Las condiciones meteorológicas actuales en los aeropuertos, que no se pudieron obtener.",
  "uncertain.airportStatus": "Si hay restricciones de tráfico aéreo en vigor, porque no se pudo acceder al servicio de la FAA.",
  "uncertain.nonUsRestrictions": "Si hay restricciones de tráfico aéreo fuera de Estados Unidos en vigor. El servicio de la FAA solo cubre aeropuertos estadounidenses.",
  "uncertain.entitlements": "Si tienes derecho a un reembolso, una compensación, comidas o alojamiento. Eso depende de tu ruta, tu billete y la causa de la incidencia.",
  "timeline.sourcesChecked": "Fuentes oficiales consultadas",
  "timeline.sourcesQueried": "{count} fuente consultada.",
  "timeline.sourcesQueried.plural": "{count} fuentes consultadas.",
  "change.weatherCategory": "Ha cambiado la categoría meteorológica de {airport}",
  "change.weatherMoved": "Ha pasado de {from} a {to}.",
  "change.weatherNowReporting": "Ahora registra {category}.",
  "change.restrictionNew": "Nueva restricción de tráfico aéreo en {airport}",
  "change.restrictionLifted": "Restricción de tráfico aéreo levantada en {airport}",
  "change.observedAirborne": "Aeronave con este indicativo observada en vuelo",
  "change.observedOnGround": "Aeronave con este indicativo observada en tierra",
  "change.observedAt": "Observada a las {time}.",
  "rights.because.eu": "Tu ruta incluye un aeropuerto de la UE o del EEE, o una aerolínea con base allí.",
  "rights.because.uk": "Tu ruta incluye un aeropuerto del Reino Unido.",
  "rights.because.us": "Tu ruta incluye un aeropuerto de Estados Unidos.",
  "rights.because.ca": "Tu ruta incluye un aeropuerto de Canadá.",
  "rights.because.montreal": "Tu viaje afecta a más de un país, así que pueden aplicarse las normas de transporte internacional.",
  "rec.captureAnnouncement.title": "Captura el texto del anuncio si puedes",
  "rec.captureAnnouncement.why": "Una foto o unas pocas palabras escritas bastan para que WAYFINDER lo traduzca y explique qué significa. El texto de los anuncios suele contener la puerta, la hora o la instrucción concreta que importa.",
  "rec.confirmWithAirline.title": "Confirma el estado del vuelo directamente con {airline}",
  "rec.confirmWithAirline.why": "Ninguna fuente pública publica el estado por vuelo. La página de estado de vuelos de la propia aerolínea es el único sitio que puede confirmar si este vuelo concreto se opera, lleva retraso o está cancelado. Consulta la app o la web de la aerolínea, no un agregador externo.",
  "rec.contactAirline.title": "Contacta con {airline} por su canal oficial",
  "rec.contactAirline.why": "La aerolínea operadora gestiona las reubicaciones, los reembolsos y la asistencia, no el aeropuerto ni una web de reservas. Contactar pronto suele dar más opciones, porque los asientos se reasignan en el orden en que se atiende a los pasajeros.",
  "rec.askRebooking.title": "Pregunta en concreto por la reubicación en el siguiente vuelo disponible",
  "rec.askRebooking.why": "Cuando un vuelo no se opera, las aerolíneas suelen poder pasarte a otro de sus vuelos y, a veces, a una aerolínea asociada. Pregunta cuál es la opción más temprana y pide que te guarden un asiento mientras decides.",
  "rec.askRefundOrCredit.title": "Pregunta si te ofrecen un reembolso o un crédito",
  "rec.askRefundOrCredit.why": "Un reembolso y un crédito de viaje no son lo mismo. Según dónde empiece y termine tu viaje, puede que tengas derecho a un reembolso si decides no viajar. Pregunta cuál te están ofreciendo antes de aceptar nada.",
  "rec.askDelayDuration.title": "Pregunta cuánto se prevé que dure el retraso",
  "rec.askDelayDuration.why": "La duración de un retraso cambia a qué tienes derecho y qué deberías hacer. La asistencia, como comidas y alojamiento, suele depender de cuánto esperes y de si el retraso se alarga toda la noche.",
  "rec.checkConnection.title": "Comprueba si tu vuelo de enlace está afectado",
  "rec.checkConnection.why": "Un retraso en el primer vuelo puede hacer que pierdas una conexión aunque el segundo vuelo opere con normalidad. Pide a la aerolínea que confirme el estado de tu conexión y que reubique todo el viaje si hace falta.",
  "rec.dontAssumeProtection.title": "No des por hecho que tu conexión está protegida",
  "rec.dontAssumeProtection.why": "Que te reubiquen en una conexión posterior y que tengas derecho a asistencia o compensación depende de tu billete, de si ambos vuelos están en una misma reserva y de las normas que se apliquen a tu ruta. Pide a la aerolínea que lo confirme por escrito.",
  "rec.verifyGate.title": "Verifica la nueva puerta en una pantalla del aeropuerto, no solo en una notificación",
  "rec.verifyGate.why": "Las puertas cambian con frecuencia y las notificaciones pueden ir por detrás de las propias pantallas del aeropuerto. Las pantallas del aeropuerto y la app de la aerolínea son los sitios más actualizados donde comprobarlo.",
  "rec.airportStatusUnavailable.title": "Consulta la página de estado operativo del propio aeropuerto",
  "rec.airportStatusUnavailable.why": "WAYFINDER no pudo obtener información actual sobre restricciones de tráfico aéreo para tus aeropuertos. La web del aeropuerto o el proveedor nacional de tráfico aéreo mostrarán si hay restricciones en vigor.",
  "rec.weatherUnavailable.title": "Comprueba el tiempo actual en ambos aeropuertos",
  "rec.weatherUnavailable.why": "No se pudieron obtener observaciones meteorológicas de uno o de ambos aeropuertos, así que WAYFINDER no puede evaluar si las condiciones están contribuyendo a la incidencia. Un servicio meteorológico nacional mostrará las condiciones actuales.",
  "rec.openAviationWeather": "Abrir meteorología aeronáutica",
  "rec.reviewRights.title": "Revisa la guía oficial de derechos de los pasajeros para tu ruta",
  "rec.reviewRights.why": "A qué tienes derecho depende de dónde empiece y termine tu viaje y de qué transportista lo opere. Leer la guía oficial de tu ruta te dice qué pedir y a qué no tienes derecho.",
  "rec.keepEvidence.title": "Guarda tu referencia de reserva, tu tarjeta de embarque y los recibos",
  "rec.keepEvidence.why": "Si más adelante necesitas reclamar gastos o una compensación, las aerolíneas piden recibos y tu referencia de reserva. Recogerlos ahora, mientras estás en el aeropuerto, es mucho más fácil que después.",
  "rec.airportHelpDesk.title": "Acude al mostrador de la aerolínea en {airport}, no a un mostrador de información general",
  "rec.airportHelpDesk.why": "Los mostradores de información del aeropuerto pueden informarte sobre el aeropuerto, pero solo la aerolínea puede cambiar tu reserva. Ve al mostrador de servicio de la propia aerolínea o al de tránsito.",
  "rec.destinationArrangements.title": "Si vas a llegar tarde a {airport}, revisa tus enlaces posteriores",
  "rec.destinationArrangements.why": "Una llegada tardía puede afectar al transporte terrestre, al alojamiento y a los viajes posteriores. Avisar pronto a los proveedores a menudo evita perder una reserva por completo.",

