  "fallback.summaryLead": "Ninguna fuente pública a la que podamos acceder publica el estado por vuelo, así que nada de lo que hay aquí puede confirmar ni descartar {problem}{flight}. Lo que sí podemos hacer es mostrarte el panorama operativo de los aeropuertos implicados y lo que solo la aerolínea puede confirmar.",
  "fallback.summaryLeadFlight": " en el vuelo {flight}",
