  "fallback.routeUnknown": "No pudimos resolver la ruta de este número de vuelo con las fuentes a las que podemos acceder, así que no podemos confirmar los aeropuertos implicados.",
  "fallback.noWeather": "No había observaciones meteorológicas aeronáuticas disponibles para estos aeropuertos, así que no podemos evaluar si el tiempo influye.",
  "fallback.aircraftObservation": "{observation} Es una observación de una aeronave con ese indicativo, no una afirmación sobre tu reserva.",
  "fallback.meaning.disruption": "En conjunto, las condiciones que vemos sugieren que hay una probabilidad real de incidencias en esta ruta. Es nuestra lectura de los datos, no una afirmación sobre tu vuelo. Confírmalo directamente con la aerolínea antes de tomar decisiones y pregunta por la reubicación cuanto antes, mientras queden asientos.",
  "fallback.meaning.noDisruption": "Las condiciones que vemos no indican por ahora incidencias en ninguno de los dos aeropuertos. Eso no confirma que tu vuelo opere con normalidad, porque no podemos ver el estado por vuelo. La página de estado de vuelos de la propia aerolínea es el único sitio que puede decírtelo.",
