  "preview.elevated": "Probabilidad elevada de incidencias",
  "preview.couldNotConfirm": "Lo que no hemos podido confirmar",
  "preview.couldNotConfirmBody": "Si el vuelo BA123 se opera, lleva retraso o está cancelado. Ninguna fuente pública publica el estado por vuelo: British Airways es el único sitio que puede confirmarlo.",
  "preview.originalSource": "Fuente original",
  "preview.departureWeather": "Meteorología en salida",
  "preview.airspaceRestriction": "Restricción de espacio aéreo",
  "preview.scheduledTimes": "Horas programadas",
