  "preview.step1.title": "Confirma el estado del vuelo con British Airways",
  "preview.step1.why": "Ninguna fuente pública publica el estado por vuelo. La página de estado de vuelos de la propia aerolínea es el único sitio que puede confirmar si este vuelo se opera.",
  "preview.step2.title": "Pregunta por la reubicación en el siguiente vuelo disponible",
  "preview.step2.why": "Los asientos se reasignan en el orden en que se atiende a los pasajeros, así que contactar pronto con la aerolínea suele dar más opciones.",
  "preview.step3.title": "Comprueba si tu conexión posterior está afectada",
  "preview.step3.why": "Un retraso en el primer tramo puede provocar una conexión perdida aunque el segundo vuelo se opere con normalidad.",
  "preview.step4.title": "Revisa la guía oficial de derechos de los pasajeros para tu ruta",
