  "preview.src3.detail": "Datos de referencia de ruta. No es el estado del vuelo en directo.",
  "live.badge": "Datos en directo",
  "live.title": "Cada dato lleva su fuente",
  "live.body": "WAYFINDER no muestra un estado que no pueda verificar. Consulta al operador o la autoridad oficial del lugar donde te encuentras, registra cuándo llegó cada respuesta y dice con claridad qué sigue sin poder confirmar.",
  "live.notShown.title": "Lo que deliberadamente no mostramos",
  "live.notShown.status.lead": "Un estado por vuelo.",
  "live.notShown.status.body": "Ninguna fuente pública a la que podamos acceder publica si un vuelo concreto está cancelado o retrasado. Suponerlo sería peor que decirlo.",
  "live.notShown.rights.lead": "Una compensación garantizada.",
  "live.notShown.rights.body": "Los reembolsos y las compensaciones dependen de tu ruta, tu billete y la causa de la incidencia. Enlazamos a la guía oficial en su lugar.",
  "live.notShown.score.lead": "Una cifra de confianza.",
  "live.notShown.score.body": "Las puntuaciones implican una precisión que no tenemos. Describimos las condiciones y el razonamiento en su lugar.",
  "live.source": "Fuente:",
  "live.route.title": "Referencia de ruta y aerolínea",
  "live.route.body": "Los números de vuelo se resuelven a una ruta, una aerolínea y un indicativo OACI publicados, así que cada consulta posterior usa los identificadores de aeropuerto correctos.",
  "live.weather.title": "Meteorología adversa y sismos",
  "live.weather.body": "Avisos oficiales activos de NOAA / National Weather Service y del Deutscher Wetterdienst, y sismos recientes del USGS, con la autoridad emisora y las zonas afectadas.",
  "live.transit.title": "Estado del transporte público",
  "live.transit.body": "Estado de líneas y servicios en directo de los propios operadores: líneas de metro, ferrocarril y autobús de Transport for London, alertas del metro de Nueva York (MTA) y avisos de servicio de BART, con la gravedad indicada por cada operador.",
  "live.roads.title": "Carreteras y avisos públicos",
  "live.roads.body": "Cortes de carril y de carretera de Caltrans, y avisos cívicos de GOV.UK, cada uno con la autoridad que lo publica y la hora en que se obtuvo.",
  "live.airspace.title": "Estado del espacio aéreo",
  "live.airspace.body": "Programas de demoras y paradas en tierra, con el motivo y el retraso medio, para los aeropuertos cubiertos por la FAA.",
