  "assist.rec.openSource": "Abrir la fuente oficial",
  "assist.rec.followOfficial.title": "Sigue las instrucciones oficiales",
  "assist.rec.followOfficial.rationale":
    "Solo la autoridad meteorológica o de emergencias puede dar instrucciones para tu zona. Lee su guía y actúa según ella.",
  "assist.rec.emergencyServices.title": "Llama a emergencias si estás en peligro",
  "assist.rec.emergencyServices.rationale":
    "Si hay riesgo inmediato para la vida o la seguridad, contacta con el número de emergencias local. WAYFINDER no puede hacerlo por ti.",
  "assist.rec.checkRoadAuthority.title": "Consulta el aviso de la autoridad de carreteras",
  "assist.rec.checkRoadAuthority.rationale":
    "Las autoridades de carreteras publican los cortes y los desvíos oficiales. Confirma la situación actual antes de viajar.",
  "assist.rec.noPhoneWhileDriving.title": "No uses el teléfono mientras conduces",
  "assist.rec.noPhoneWhileDriving.rationale":
    "Consulta esta información antes de salir o detente en un lugar seguro. Usar el teléfono al volante es peligroso y es ilegal en muchos sitios.",
  "assist.rec.followSignedDiversion.title": "Sigue el desvío señalizado",
  "assist.rec.followSignedDiversion.rationale":
    "WAYFINDER no puede verificar una ruta alternativa segura. Usa solo el desvío señalizado por la autoridad de carreteras.",
  "assist.rec.confirmWithOperator.title": "Confirma con el operador",
  "assist.rec.confirmWithOperator.rationale":
    "Los operadores confirman el estado de un servicio concreto. Nuestras fuentes informan de condiciones de la red, no de tu trayecto.",
  "assist.rec.checkAlternative.title": "Pregunta al personal por rutas alternativas",
  "assist.rec.checkAlternative.rationale":
    "Cuando una línea está afectada, el personal de la estación puede confirmar servicios alternativos válidos.",
  "assist.rec.identifyProvider.title": "Identifica quién es responsable",
  "assist.rec.identifyProvider.rationale":
    "El proveedor de transporte o alojamiento que causó la incidencia suele ser quien puede ayudar.",
  "assist.rec.contactSupport.title": "Contacta con el canal de soporte del proveedor",
  "assist.rec.contactSupport.rationale":
    "Usa el canal oficial de soporte para que tu solicitud quede registrada y se pueda seguir.",
  "assist.rec.keepEvidence.title": "Guarda tus billetes y recibos",
  "assist.rec.keepEvidence.rationale":
    "Conserva billetes, referencias de reserva y recibos. Cualquier derecho depende del proveedor, la ruta y las circunstancias.",
  "assist.rec.confirmWithProvider.title": "Confirma con el proveedor del servicio",
  "assist.rec.confirmWithProvider.rationale":
    "Los avisos públicos los publica el organismo responsable. Confirma la situación actual directamente con ellos.",
  "assist.rec.describeMore.title": "Añade algo más de detalle",
  "assist.rec.describeMore.rationale":
    "Indícanos el país o la ciudad y qué ha pasado. Eso nos permite encontrar una fuente que cubra tu situación.",
  "assist.rec.contactResponsibleBody.title": "Contacta con la organización responsable",
