  "details.connectionTimeHelp": "कनेक्शन के लिए आपके पास कितना समय है।",
  "announce.label": "घोषणा का पाठ",
  "announce.helpForm": "घोषणा में जो कहा गया वह किसी भी भाषा में लिखें या चिपकाएँ। आपका स्थिति पृष्ठ खुलने पर WAYFINDER इसे अनुवाद करके अर्थ समझाएगा।",
  "announce.placeholder": "उदाहरण: फ़्रैंकफ़र्ट जाने वाली उड़ान LH456 के यात्री, गेट B42 में बदल गया है।",
  "details.bookingReference": "बुकिंग संदर्भ",
  "details.bookingReferenceHelp": "वैकल्पिक। छह अक्षर, जैसे ABC123। यह आपके ब्राउज़र में रहता है और केवल आपके बनाए सारांशों में उपयोग होता है।",
  "flow.step1": "हम आपके उड़ान नंबर को प्रकाशित मार्ग, एयरलाइन और हवाई अड्डा पहचानकर्ताओं से जोड़ते हैं।",
  "flow.step2": "हम विमानन मौसम, वायुक्षेत्र स्थिति और मार्ग संदर्भ डेटा प्राप्त करते हैं, और हर उत्तर के आने का समय दर्ज करते हैं।",
  "flow.step3": "हम स्पष्ट बताते हैं कि हम क्या पुष्ट नहीं कर सके, और उस आधिकारिक स्रोत की ओर इंगित करते हैं जो कर सकता है।",
  "flow.whySoLittle": "हम इतना कम क्यों पूछते हैं",
  "flow.whySoLittleBody": "केवल उड़ान नंबर आवश्यक है। हवाई अड्डे, तिथियाँ और कनेक्शन विवरण उत्तर को सटीक बनाते हैं, पर समय की कमी वाले यात्री को एक ही फ़ील्ड से उपयोगी कुछ मिलना चाहिए।",
  "assist.picker.noLiveData": "कोई लाइव स्रोत नहीं",
