const CATALOGUE: Record<LocaleCode, Messages> = {
  en,
  es,
  fr,
  de,
  pt,
  ar,
  zh,
  ja,
  hi,
};

/**
 * Looks up a message, falling back to English and then to the key itself so a
 * missing translation degrades to readable text instead of an empty element.
 */
export function translate(
  locale: LocaleCode,
  key: string,
  params?: Record<string, string | number>,
): string {
  const template = CATALOGUE[locale]?.[key] ?? CATALOGUE.en[key] ?? key;
  if (!params) return template;
  return template.replace(/\{(\w+)\}/g, (match, name: string) => {
    const value = params[name];
    return value === undefined ? match : String(value);
  });
}

export function getMessages(locale: LocaleCode): Messages {
  return { ...CATALOGUE.en, ...(CATALOGUE[locale] ?? {}) };
}

export function hasTranslation(locale: LocaleCode, key: string): boolean {
  return Boolean(CATALOGUE[locale]?.[key]);
}
